// @ts-nocheck
import * as TSL from "three/tsl";
import * as WEBGPU from "three/webgpu";
import { nightK, screenK } from "../render/daynight.ts";
import { uScrBoost, uScrKnee, uScrTop } from "./screenlights.ts";

const live = (source) => {
  const node = TSL.uniform(source.value);
  node.onRenderUpdate(() => { node.value = source.value; });
  return node;
};
const hash = (p) => TSL.fract(TSL.sin(TSL.dot(p, TSL.vec2(12.9898, 78.233))).mul(43758.5453));

/** TSL implementation of the city signage material. Geometry keeps the aSig/aLoc data generated by signage.ts. */
export function createSignageNodeMaterial(ads, signs, noise, art) {
  // The custom colorNode samples vertexColor() itself.
  const material = new WEBGPU.MeshStandardNodeMaterial({ vertexColors: false, roughness: 0.6 });
  material.name = "CitySignage.TSL";
  const uv = TSL.uv();
  const local = TSL.attribute("aLoc", "vec2");
  const sig = TSL.attribute("aSig", "vec2");
  const kind = TSL.round(sig.x);
  const world = TSL.positionWorld;
  const base = TSL.vertexColor().rgb;
  const imageUv = TSL.select(
    uv.x.greaterThan(3.5),
    uv.sub(TSL.vec2(4, 0)),
    TSL.select(uv.x.greaterThan(1.5), uv.sub(TSL.vec2(2, 0)), uv),
  );
  const adTexel = TSL.texture(ads, imageUv);
  const signTexel = TSL.texture(signs, imageUv);
  const artTexel = TSL.texture(art, imageUv);
  const mapped = TSL.select(uv.x.greaterThan(3.5), artTexel.rgb,
    TSL.select(uv.x.greaterThan(1.5), signTexel.rgb, adTexel.rgb));
  const noiseA = TSL.texture(noise, TSL.vec2(world.x, world.z).add(TSL.vec2(world.y.mul(0.7), world.y.mul(-0.4))).div(9)).rgb;
  const noiseB = TSL.texture(noise, TSL.vec2(world.x.mul(0.6), world.z.mul(0.6)).add(TSL.vec2(world.y.mul(-0.5), world.y.mul(0.8))).div(1.7)).rgb;
  const lum = TSL.dot(mapped, TSL.vec3(0.2126, 0.7152, 0.0722));
  const night = live(nightK);
  const screen = live(screenK);
  const boost = live(uScrBoost);
  const knee = live(uScrKnee);
  const top = live(uScrTop);

  const vinyl = TSL.mix(mapped, TSL.vec3(lum), 0.1).mul(0.95).add(0.005);
  const fadedVinyl = TSL.mix(vinyl, TSL.vec3(lum.mul(0.9).add(0.06)), TSL.smoothstep(0.35, 0.8, noiseA.b).mul(0.06).add(local.y.mul(0.02)));
  const adWall = TSL.mix(mapped.mul(0.66).add(0.05), base, TSL.smoothstep(0.6, 0.76, noiseA.r.mul(0.7).add(noiseB.g.mul(0.45))).mul(0.85).add(0.1));
  const led = mapped.mul(0.12);
  const lightbox = mapped.mul(0.85);
  const awningStripe = TSL.select(TSL.fract(local.x.mul(sig.y)).greaterThan(0.5), TSL.vec3(0.62, 0.58, 0.5), base);
  let color = base;
  color = TSL.select(kind.equal(1), fadedVinyl, color);
  color = TSL.select(kind.equal(2), adWall, color);
  color = TSL.select(kind.equal(3), led, color);
  color = TSL.select(kind.equal(4), lightbox, color);
  color = TSL.select(kind.equal(6), TSL.mix(color, TSL.vec3(0.9, 0.8, 0.6), 0.6), color);
  color = TSL.select(kind.equal(7), awningStripe.mul(TSL.float(0.82).add(noiseB.g.mul(0.3))), color);
  color = TSL.select(kind.equal(8).or(kind.equal(9)), mapped.mul(TSL.float(0.8).add(noiseB.r.mul(0.3))), color);
  material.colorNode = color;

  const bulbCoord = TSL.fract(uv).sub(0.5);
  const bulb = TSL.float(1).sub(TSL.smoothstep(0.2, 0.34, bulbCoord.length()));
  const flicker = TSL.float(0.85).add(hash(TSL.floor(uv).add(TSL.vec2(world.x, world.z))).mul(0.15));
  const ledGain = screen.mul(TSL.float(1).add(boost.sub(1).mul(night)));
  const peak = TSL.max(mapped.r, TSL.max(mapped.g, mapped.b));
  const screenShoulder = knee.add(top.sub(knee).mul(TSL.float(1).sub(TSL.exp(peak.sub(knee).div(top.sub(knee).max(1e-4)).negate()))));
  const shoulderScale = TSL.select(peak.greaterThan(knee), screenShoulder.div(peak.max(1e-4)), TSL.float(1));
  const ledEmissive = mapped.mul(sig.y).mul(ledGain).mul(TSL.mix(1, shoulderScale, night));
  const bulbEmissive = TSL.vec3(1, 0.78, 0.46).mul(sig.y).mul(bulb).mul(flicker).mul(TSL.mix(1, 0.3, night));
  const signEmissive = mapped.mul(sig.y).mul(TSL.mix(1, 1.7, night));
  const windowLetter = mapped.mul(0.35).mul(night);
  material.emissiveNode = TSL.select(kind.equal(3), ledEmissive,
    TSL.select(kind.equal(4), signEmissive,
      TSL.select(kind.equal(6), bulbEmissive,
        TSL.select(kind.equal(9), windowLetter, TSL.vec3(0)))));
  material.roughnessNode = TSL.select(kind.equal(1), TSL.float(0.48).add(noiseB.g.mul(0.34)),
    TSL.select(kind.equal(2).or(kind.equal(7)), TSL.float(0.88),
      TSL.select(kind.equal(3), TSL.float(0.25), TSL.select(kind.equal(4), TSL.float(0.35), TSL.float(0.55)))));
  material.metalnessNode = TSL.select(kind.equal(8), TSL.float(0.85), TSL.select(kind.equal(9), TSL.select(mapped.r.greaterThan(mapped.b.mul(1.4)), 0.6, 0), 0));
  material.maskNode = TSL.select(kind.equal(8).or(kind.equal(9)), TSL.smoothstep(0.3, 0.5, lum).greaterThan(0.5), true);
  return material;
}
